UPDATE POST_COMMENT SET CONTENT = #{content}, UPDATED_AT = SYSTIMESTAMP
WHERE COMMENT_ID = #{commentId} AND POST_ID = #{postId} 
	AND MEMBER_ID = #{memberId} AND PARENT_COMMENT_ID IS NULL AND STATUS = 0

UPDATE POST_COMMENT SET STATUS = 2, UPDATED_AT = SYSTIMESTAMP
WHERE COMMENT_ID = #{commentId} AND POST_ID = #{postId} 
	AND MEMBER_ID = #{memberId} AND PARENT_COMMENT_ID IS NULL AND STATUS = 0

UPDATE POST_COMMENT SET STATUS = 1, UPDATED_AT = SYSTIMESTAMP
WHERE COMMENT_ID = #{commentId} AND POST_ID = #{postId} 
	AND PARENT_COMMENT_ID IS NULL AND STATUS = 0
